// Aim range is decoupled from the ESP draw distance: aim.cpp's walk once reused esp_within_draw_distance on
// g_cfg.espdrawdist, the Visuals tab's setting; the aim assist now has its own g_cfg.aimrange (aim_within_range). Row
// bindings are checked in the Combat tab's block above; this is the pure config/predicate side.
void tb_0057_phase_4_task_1_aim() {
    config_load(tb_path("Z:|does|not|exist.ini"));
    CHECK(g_cfg.aimrange == 32768);                       // a range, defaults to "everything"
    CHECK(clamp_int(0, 512, 32768) == 512 && clamp_int(99999, 512, 32768) == 32768);
    CHECK( aim_within_range(6000, 6144));
    CHECK(!aim_within_range(6145, 6144));
    CHECK( aim_within_range(6144, 6144));                 // inclusive boundary
    CHECK(!aim_within_range(20000, 6144) && aim_within_range(20000, 32768));
    // The two ranges are independent: an ESP-visible enemy outside aimrange is
    // not a candidate, and an aim candidate inside aimrange but outside espdrawdist is still a candidate.
    CHECK( aim_within_range(9000, 10000) && !esp_within_draw_distance(9000, 8000));

    CHECK(AIM_RANGE_MIN == 512);
    CHECK(AIM_RANGE_MAX == 32768);
    CHECK(AIM_RANGE_DEFAULT == AIM_RANGE_MAX);
    CHECK(AIM_RANGE_MIN == ESP_DRAWDIST_MIN);
    // The ESP's top is 256 m (for the cutaway view); the aim's stays at 64 m, which is what makes them separate
    // constants.
    CHECK(AIM_RANGE_MAX == 32768);
    CHECK(AIM_RANGE_MAX < ESP_DRAWDIST_MAX);

    CHECK(aim_range_clamped(999999) == 32768);
    CHECK(aim_range_clamped(32769)  == 32768);
    CHECK(aim_range_clamped(0)      == 512);
    CHECK(aim_range_clamped(-5)     == 512);
    CHECK(aim_range_clamped(511)    == 512);
    CHECK(aim_range_clamped(512)    == 512);
    CHECK(aim_range_clamped(513)    == 513);
    CHECK(aim_range_clamped(6144)   == 6144);
    CHECK(aim_range_clamped(32767)  == 32767);
    CHECK(aim_range_clamped(32768)  == 32768);
    CHECK(aim_range_clamped(2147483647)      == 32768);
    CHECK(aim_range_clamped(-2147483647 - 1) == 512);

    {
      const char* t = "test_aim_range_task1.ini";
      FILE* f = nullptr;

      fopen_s(&f, t, "w");
      fputs("[nukepanel]\naimrange=7000\n", f);
      fclose(f);
      config_load(t);
      CHECK(g_cfg.aimrange == 7000);
      CHECK(config_save(t));
      config_load(t);
      CHECK(g_cfg.aimrange == 7000);   // survives the save, not just the load

      fopen_s(&f, t, "w"); fputs("[nukepanel]\naimrange=999999\n", f); fclose(f);
      config_load(t); CHECK(g_cfg.aimrange == 32768);
      fopen_s(&f, t, "w"); fputs("[nukepanel]\naimrange=32769\n", f); fclose(f);
      config_load(t); CHECK(g_cfg.aimrange == 32768);
      fopen_s(&f, t, "w"); fputs("[nukepanel]\naimrange=32767\n", f); fclose(f);
      config_load(t); CHECK(g_cfg.aimrange == 32767);
      fopen_s(&f, t, "w"); fputs("[nukepanel]\naimrange=0\n", f); fclose(f);
      config_load(t); CHECK(g_cfg.aimrange == 512);
      fopen_s(&f, t, "w"); fputs("[nukepanel]\naimrange=-7\n", f); fclose(f);
      config_load(t); CHECK(g_cfg.aimrange == 512);
      fopen_s(&f, t, "w"); fputs("[nukepanel]\naimrange=511\n", f); fclose(f);
      config_load(t); CHECK(g_cfg.aimrange == 512);
      fopen_s(&f, t, "w"); fputs("[nukepanel]\naimrange=512\n", f); fclose(f);
      config_load(t); CHECK(g_cfg.aimrange == 512);

      fopen_s(&f, t, "w"); fputs("[nukepanel]\naimrange=999999\n", f); fclose(f);
      config_load(t);
      CHECK(config_save(t));
      config_load(t);
      CHECK(g_cfg.aimrange == 32768);

      g_cfg.aimrange = 1234;
      fopen_s(&f, t, "w"); fputs("[nukepanel]\naimon=1\n", f); fclose(f);
      config_load(t);
      CHECK(g_cfg.aimrange == AIM_RANGE_DEFAULT);

      remove(t);
    }
    config_load(tb_path("Z:|does|not|exist.ini"));   // leave the defaults in place
  }


void tb_0064_capture_state_machine_every_transition() {
    const KeyCapState idle = { KEYCAP_IDLE, -1 };
    KeyCapEvent e = { KEYCAP_EV_CLICK, BIND_ROW_CAMERA, 0 };
    KeyCapResult r = keycap_step(idle, e);
    CHECK(r.state.phase == KEYCAP_ARMED);
    CHECK(r.state.row == BIND_ROW_CAMERA);
    CHECK(r.boundRow == -1 && r.boundVk == 0);
    CHECK(!r.consumed);
    const KeyCapState armed = r.state;
    KeyCapEvent key = { KEYCAP_EV_KEY, -1, 0x71 };
    r = keycap_step(armed, key);
    CHECK(r.state.phase == KEYCAP_IDLE && r.state.row == -1);
    CHECK(r.boundRow == BIND_ROW_CAMERA);
    CHECK(r.boundVk == 0x71);
    CHECK(r.consumed);
    KeyCapEvent m5 = { KEYCAP_EV_MOUSE, -1, VK_BIND_XBUTTON2 };
    r = keycap_step(armed, m5);
    CHECK(r.state.phase == KEYCAP_IDLE);
    CHECK(r.boundRow == BIND_ROW_CAMERA && r.boundVk == VK_BIND_XBUTTON2);
    CHECK(r.consumed);
    // Mouse 1 is refused and the capture stays armed: it's the click that armed
    // the row, so binding it would make the row unclickable forever.
    KeyCapEvent m1 = { KEYCAP_EV_MOUSE, -1, VK_BIND_LBUTTON };
    r = keycap_step(armed, m1);
    CHECK(r.state.phase == KEYCAP_ARMED && r.state.row == BIND_ROW_CAMERA);
    CHECK(r.boundRow == -1 && r.boundVk == 0);
    CHECK(!r.consumed);
    KeyCapEvent esc = { KEYCAP_EV_ESCAPE, -1, 0 };
    r = keycap_step(armed, esc);
    CHECK(r.state.phase == KEYCAP_IDLE && r.state.row == -1);
    CHECK(r.boundRow == -1 && r.boundVk == 0);
    CHECK(r.consumed);
    r = keycap_step(idle, esc);
    CHECK(r.state.phase == KEYCAP_IDLE);
    CHECK(!r.consumed);
    r = keycap_step(idle, key);
    CHECK(r.state.phase == KEYCAP_IDLE && r.boundRow == -1 && !r.consumed);
    r = keycap_step(idle, m5);
    CHECK(r.state.phase == KEYCAP_IDLE && r.boundRow == -1 && !r.consumed);
    KeyCapEvent other = { KEYCAP_EV_CLICK, BIND_ROW_TELEPORT, 0 };
    r = keycap_step(armed, other);
    CHECK(r.state.phase == KEYCAP_ARMED && r.state.row == BIND_ROW_TELEPORT);
    CHECK(r.boundRow == -1);
    KeyCapEvent same = { KEYCAP_EV_CLICK, BIND_ROW_CAMERA, 0 };
    r = keycap_step(armed, same);
    CHECK(r.state.phase == KEYCAP_ARMED && r.state.row == BIND_ROW_CAMERA);
    CHECK(r.boundRow == -1);
    // Closing the panel disarms: left armed, it would eat the next key press in game.
    KeyCapEvent close = { KEYCAP_EV_CLOSE, -1, 0 };
    r = keycap_step(armed, close);
    CHECK(r.state.phase == KEYCAP_IDLE && r.state.row == -1 && !r.consumed);
    r = keycap_step(idle, close);
    CHECK(r.state.phase == KEYCAP_IDLE);
    KeyCapEvent none = { KEYCAP_EV_NONE, -1, 0 };
    r = keycap_step(armed, none);
    CHECK(r.state.phase == KEYCAP_ARMED && r.state.row == BIND_ROW_CAMERA && !r.consumed);
    r = keycap_step(idle, none);
    CHECK(r.state.phase == KEYCAP_IDLE && !r.consumed);
    KeyCapEvent badRow = { KEYCAP_EV_CLICK, BIND_ROW_COUNT, 0 };
    r = keycap_step(idle, badRow);
    CHECK(r.state.phase == KEYCAP_IDLE && r.state.row == -1);
    KeyCapEvent negRow = { KEYCAP_EV_CLICK, -1, 0 };
    r = keycap_step(idle, negRow);
    CHECK(r.state.phase == KEYCAP_IDLE && r.state.row == -1);
    KeyCapEvent zero = { KEYCAP_EV_KEY, -1, 0 };
    r = keycap_step(armed, zero);
    CHECK(r.state.phase == KEYCAP_ARMED && r.boundRow == -1 && !r.consumed);
    CHECK(BIND_ROW_COUNT == 4);
  }


void tb_0071_combat_tab_s_button_row() {
    // "Aimbot button" is the aim row's own capture: clicking the row (found by label, never a coordinate) arms the
    // capture and the bind lands on aimbind alone. It lives on the Settings tab (HOTKEYS), live even with the aimbot
    // off since a hotkey can be set independent of its feature.
    const int savedTab = menu_active_tab();
    const CombatState saved = combat_snapshot();
    const CombatState st = { 0, 0, VK_BIND_XBUTTON1, 0, 0, 0, 30, 0, 0, 70, 0, 45, 32768 };
    menu_gamecfg_load(0);
    combat_restore(st);
    menu_set_tab(TAB_SETTINGS);
    g_ui.mx = -1; g_ui.my = -1; g_ui.down = false; g_ui.pressed = false;
    canvas_record_begin();
    menu_draw(3440, 1440);
    canvas_record_end();
    const CanvasOp* row = canvas_record_find_text("Aimbot button");
    CHECK(row);
    if (row) {
      const UiRect p = menu_panel_rect(3440, 1440);
      bool armedSomewhere = false;
      for (int x = p.x; x < p.x + p.w && !armedSomewhere; x++) {
        combat_restore(st);                    // also disarms, see combat_restore
        menu_set_tab(TAB_SETTINGS);
        g_ui.mx = x; g_ui.my = row->y; g_ui.down = false; g_ui.pressed = true;
        menu_draw(3440, 1440);
        if (menu_keycap_armed()) armedSomewhere = true;
      }
      CHECK(armedSomewhere);                   // live with the aimbot itself off
      g_ui.mx = -1; g_ui.my = -1; g_ui.down = false; g_ui.pressed = false;
      CHECK(combat_changed(st) == 0);
      menu_keycap_bind(VK_BIND_XBUTTON2);
      CHECK(!menu_keycap_armed());
      CHECK(g_cfg.aimbind == VK_BIND_XBUTTON2);
      CHECK(combat_changed(st) == CF_AIMBUTTON);   // and no other combat field
      menu_set_tab(TAB_SETTINGS);
      canvas_record_begin();
      menu_draw(3440, 1440);
      canvas_record_end();
      CHECK(canvas_record_find_text("Mouse 5") != nullptr);
      CHECK(canvas_record_find_text("Mouse 4") == nullptr);
    }
    combat_restore(saved);
    menu_set_tab(savedTab);
    g_ui.mx = -1; g_ui.my = -1; g_ui.down = false; g_ui.pressed = false;
    g_cfgDirty = false;
  }


// The aimbot aims one tic ahead of the shot: processinput saves oposx/y/z, moves the player, then calls `shoot`, but
// the aimbot's solve runs after processinput returns -- so both ends of the shot were one tic stale. These four pure
// helpers advance both ends by exactly one tic; see target.h.
void tb_0106_aim_ahead() {
    CHECK(aim_ahead_step(0, 0, AIM_AHEAD_MAX_STEP) == 0);
    CHECK(aim_ahead_step(12345, 12345, AIM_AHEAD_MAX_STEP) == 0);
    CHECK(aim_ahead_step(12385, 12345, AIM_AHEAD_MAX_STEP) == 40);
    CHECK(aim_ahead_step(12305, 12345, AIM_AHEAD_MAX_STEP) == -40);
    CHECK(aim_ahead_step(-12305, -12345, AIM_AHEAD_MAX_STEP) == 40);
    CHECK(aim_ahead_step(-12385, -12345, AIM_AHEAD_MAX_STEP) == -40);
    CHECK(AIM_AHEAD_MAX_STEP == 1024);
    CHECK(aim_ahead_step(AIM_AHEAD_MAX_STEP, 0, AIM_AHEAD_MAX_STEP) == AIM_AHEAD_MAX_STEP);
    CHECK(aim_ahead_step(-AIM_AHEAD_MAX_STEP, 0, AIM_AHEAD_MAX_STEP) == -AIM_AHEAD_MAX_STEP);
    CHECK(aim_ahead_step(1025, 0, AIM_AHEAD_MAX_STEP) == 0);
    CHECK(aim_ahead_step(-1025, 0, AIM_AHEAD_MAX_STEP) == 0);
    // Real measured run steps (+242 diagonal, +600) both pass, where the old
    // 256-unit cap left the diagonal reading inside it only by chance.
    CHECK(aim_ahead_step(242, 0, AIM_AHEAD_MAX_STEP) == 242);
    CHECK(aim_ahead_step(600, 0, AIM_AHEAD_MAX_STEP) == 600);
    CHECK(aim_ahead_step(1000000, 0, AIM_AHEAD_MAX_STEP) == 0);
    // INT_MAX - INT_MIN wraps to -1 in int arithmetic (inside the cap, wrong
    // direction); widened, it is far above the cap and answers 0.
    CHECK(aim_ahead_step(2147483647, -2147483647 - 1, AIM_AHEAD_MAX_STEP) == 0);
    CHECK(aim_ahead_step(-2147483647 - 1, 2147483647, AIM_AHEAD_MAX_STEP) == 0);

    // Z cap separately: Build z is 16x finer than xy, so the vertical cap needs
    // a bigger number. AIM_AHEAD_MAX_STEP_Z IS AIM_VEL_MAX_FALL, not a second literal that could drift from it.
    CHECK(AIM_AHEAD_MAX_STEP_Z == AIM_VEL_MAX_FALL);
    CHECK(AIM_AHEAD_MAX_STEP_Z == 6144);
    CHECK(aim_ahead_step(4096, 0, AIM_AHEAD_MAX_STEP_Z) == 4096);
    CHECK(aim_ahead_step(4096, 0, AIM_AHEAD_MAX_STEP) == 0);
    CHECK(aim_ahead_step(AIM_AHEAD_MAX_STEP_Z, 0, AIM_AHEAD_MAX_STEP_Z) == AIM_AHEAD_MAX_STEP_Z);
    CHECK(aim_ahead_step(6145, 0, AIM_AHEAD_MAX_STEP_Z) == 0);

    {
      const Point3 eye = { 1000, -2000, 3000 };
      const Point3 a = aim_ahead_origin(eye, 40, -7, 13);
      CHECK(a.x == 1040 && a.y == -2007 && a.z == 3013);
      const Point3 same = aim_ahead_origin(eye, 0, 0, 0);
      CHECK(same.x == eye.x && same.y == eye.y && same.z == eye.z);
      const Point3 hi = { 2147483647, 2147483647, 2147483647 };
      const Point3 sat = aim_ahead_origin(hi, 40, 1, 256);
      CHECK(sat.x == 2147483647 && sat.y == 2147483647 && sat.z == 2147483647);
      const Point3 lo = { -2147483647 - 1, -2147483647 - 1, -2147483647 - 1 };
      const Point3 satlo = aim_ahead_origin(lo, -40, -1, -256);
      CHECK(satlo.x == -2147483647 - 1 && satlo.y == -2147483647 - 1);
      CHECK(satlo.z == -2147483647 - 1);
    }

    {
      const Point3 raw = { 6000, 500, -4000 };
      const Point3 t = aim_ahead_target(raw, 30, -12, 96);
      CHECK(t.x == 6030 && t.y == 488 && t.z == -3904);
      const Point3 tx = aim_ahead_target(raw, 30, 0, 0);
      CHECK(tx.x == raw.x + 30 && tx.y == raw.y && tx.z == raw.z);
      const Point3 still = aim_ahead_target(raw, 0, 0, 0);
      CHECK(still.x == raw.x && still.y == raw.y && still.z == raw.z);
      const Point3 hi = { 2147483647, 2147483647, 2147483647 };
      const Point3 sat = aim_ahead_target(hi, 1, 840, 6144);
      CHECK(sat.x == 2147483647 && sat.y == 2147483647 && sat.z == 2147483647);
    }

    {
      const WeaponInfo hs = target_weapon_info(1);      // pistol: hitscan
      const Point3 eye = { 0, 0, 0 };
      const Point3 raw = { 4096, 0, 0 };
      const Point3 moved = { 0, 40, 0 };                // one tic of strafe

      const AimSolution stale = target_solve(eye, raw, 0, hs);
      const AimSolution ahead =
          target_solve(aim_ahead_origin(eye, 0, 40, 0), raw, 0, hs);
      const AimSolution byHand = target_solve(moved, raw, 0, hs);
      CHECK(stale.valid && ahead.valid && byHand.valid);
      CHECK(ahead.ang == byHand.ang && ahead.horiz == byHand.horiz);
      CHECK(ahead.ang != stale.ang);                    // the correction is real
      CHECK(aim_shot_angerr(ahead.ang, stale.ang) < 0);

      const AimSolution zero =
          target_solve(aim_ahead_origin(eye, 0, 0, 0), raw, 0, hs);
      CHECK(zero.ang == stale.ang && zero.horiz == stale.horiz);
      CHECK(zero.valid == stale.valid);

      const int warped = aim_ahead_step(1000000, 0, AIM_AHEAD_MAX_STEP);
      const AimSolution warp =
          target_solve(aim_ahead_origin(eye, 0, warped, 0), raw, 0, hs);
      CHECK(warp.ang == stale.ang && warp.horiz == stale.horiz);
    }

    CHECK(aim_shot_angerr(0, 0) == 0);
    CHECK(aim_shot_angerr(1234, 1234) == 0);
    CHECK(aim_shot_angerr(5, 2040) == 13);
    CHECK(aim_shot_angerr(2040, 5) == -13);
    CHECK(aim_shot_angerr(100, 60) == 40);
    CHECK(aim_shot_angerr(60, 100) == -40);
    CHECK(aim_shot_angerr(1024, 0) == -1024);
    CHECK(aim_shot_angerr(0, 1024) == -1024);
    for (int a = 0; a < 2048; a += 7) {
      const int err = aim_shot_angerr(a, 300);
      CHECK(err >= -1024 && err <= 1023);
    }
    CHECK(aim_shot_angerr(4096 + 5, 2040) == 13);
    CHECK(aim_shot_angerr(-2048 + 5, 2040) == 13);
    CHECK(aim_shot_angerr(2147483647, 0) >= -1024);
    CHECK(aim_shot_angerr(-2147483647 - 1, 0) <= 1023);
  }

void tb_0114_hold_view_rule() {
  // All eight combinations, written out so a reader can see which one holds. wroteLastTic  menuOpen  lockout
  CHECK( aim_hold_view_rule(true,  false, false));   // the aimbot steers: hold
  CHECK(!aim_hold_view_rule(true,  false, true ));   // the lockout owns input
  CHECK(!aim_hold_view_rule(true,  true,  false));   // the panel owns input
  CHECK(!aim_hold_view_rule(true,  true,  true ));
  CHECK(!aim_hold_view_rule(false, false, false));   // no write last tic: the mouse is the player's
  CHECK(!aim_hold_view_rule(false, false, true ));
  CHECK(!aim_hold_view_rule(false, true,  false));
  CHECK(!aim_hold_view_rule(false, true,  true ));

  for (int m = 0; m < 2; m++)
    for (int l = 0; l < 2; l++)
      CHECK(!aim_hold_view_rule(false, m != 0, l != 0));
  CHECK(!aim_hold_view_rule(true, true, false) && !aim_hold_view_rule(true, false, true));
}
